const {chromium} = require('playwright');
const assert = require('node:assert/strict');
(async () => {
 const browser = await chromium.launch({headless:true,args:['--no-sandbox']});
 const page = await browser.newPage({viewport:{width:1440,height:1080}});
 const errors = []; page.on('pageerror', e => errors.push(e.message));
 await page.goto('http://localhost:5173');
 await page.evaluate(() => document.fonts.ready);
 await page.screenshot({path:'/tmp/slovo-desktop.png',fullPage:true});
 const editor = page.locator('#markdown-input');
 await editor.fill('# Проверка\\n\\n**Жирный** и *курсив*.\\n\\n- Один\\n- Два\\n\\n> Цитата\\n\\n[Ссылка](https://example.com)\\n\\n- [x] Готово\\n\\n| A | B |\\n| - | - |\\n| 1 | 2 |');
 await page.locator('.markdown-preview h1').filter({hasText:'Проверка'}).waitFor();
 assert.equal(await page.locator('.markdown-preview strong').innerText(),'Жирный');
 assert.equal(await page.locator('.markdown-preview em').innerText(),'курсив');
 assert.equal(await page.locator('.markdown-preview table').count(),1);
 assert.equal(await page.locator('.markdown-preview input:checked').count(),1);
 await editor.fill('слово');
 await editor.evaluate(el => {el.focus();el.setSelectionRange(0,5)});
 await page.getByRole('button',{name:'Жирный',exact:true}).click();
 assert.equal(await editor.inputValue(),'**слово**');
 assert.equal(await page.locator('.markdown-preview strong').innerText(),'слово');
 await editor.fill('текст');
 await editor.selectText();
 await editor.press('Control+i');
 assert.equal(await editor.inputValue(),'*текст*');
 await page.locator('#note-title').fill('Тест сохранения');
 await page.getByRole('button',{name:'Сохранить заметку',exact:true}).click();
 await page.getByText('Все изменения сохранены').waitFor();
 await page.reload();
 assert.equal(await page.locator('#note-title').inputValue(),'Тест сохранения');
 assert.equal(await page.locator('#markdown-input').inputValue(),'*текст*');
 await page.getByRole('button',{name:'Только предпросмотр',exact:true}).click();
 assert.equal(await page.locator('#markdown-input').count(),0);
 await page.getByRole('button',{name:'Редактор и предпросмотр',exact:true}).click();
 await page.getByRole('button',{name:'На весь экран',exact:true}).click();
 assert.equal(await page.locator('.editor-expanded').count(),1);
 await page.keyboard.press('Escape');
 assert.equal(await page.locator('.editor-expanded').count(),0);
 await page.getByRole('button',{name:'Шпаргалка Markdown',exact:true}).click();
 await page.getByRole('dialog').waitFor();
 await page.keyboard.press('Escape');
 await page.getByRole('button',{name:'Мои заметки',exact:true}).click();
 assert.ok((await page.getByRole('dialog').innerText()).includes('Тест сохранения'));
 await page.keyboard.press('Escape');
 await page.locator('#markdown-input').fill('');
 await page.getByText('Здесь появятся ваши мысли').waitFor();
 await page.locator('#markdown-input').fill('[x](javascript:alert(1))\\n<script>window.pwned=true</script>');
 assert.ok("'!(await page.locator('"'.markdown-preview').innerHTML()).includes('href=\"javascript:'));
 assert.equal(await page.evaluate(()=>window.pwned),undefined);
 await page.evaluate(()=>localStorage.clear()); await page.reload();
 await page.setViewportSize({width:390,height:844});
 await page.screenshot({path:'/tmp/slovo-mobile.png',fullPage:true});
 assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth <= innerWidth));
 assert.equal(errors.length,0,errors.join('\\n'));
 console.log('PASS: live Markdown, GFM, selection formatting, keyboard shortcut, save/reload, view modes, help, notes, empty state, safe rendering, mobile width, no runtime errors.');
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
